/**
 * Definition for singly-linked list.
 * class ListNode {
 *     val: number
 *     next: ListNode | null
 *     constructor(val?: number, next?: ListNode | null) {
 *         this.val = (val===undefined ? 0 : val)
 *         this.next = (next===undefined ? null : next)
 *     }
 * }
 */

function mergeKLists(lists: Array<ListNode | null>): ListNode | null {
  // Сливает списки lists[lo..hi] в один — как сортировка слиянием
  function merge(lo: number, hi: number): ListNode | null {
    // Пустой диапазон (бывает только при lists = [])
    if (lo > hi) return null;
    // Один список уже отсортирован — это база рекурсии
    if (lo === hi) return lists[lo];

    // Делим диапазон пополам, сливаем каждую половину, затем — два результата
    const mid = Math.floor((lo + hi) / 2);
    return mergeTwo(merge(lo, mid), merge(mid + 1, hi));
  }

  return merge(0, lists.length - 1);
}

// Классическое слияние двух отсортированных списков
function mergeTwo(a: ListNode | null, b: ListNode | null): ListNode | null {
  // Фиктивная голова: не нужно отдельно выбирать первый узел
  const dummy = new ListNode(0);
  let tail = dummy;

  while (a && b) {
    // Пришиваем меньший из двух текущих узлов
    if (a.val <= b.val) {
      tail.next = a;
      a = a.next;
    } else {
      tail.next = b;
      b = b.next;
    }
    tail = tail.next;
  }

  // Остаток одного из списков пришиваем целиком
  tail.next = a ?? b;
  return dummy.next;
}

// Время: O(N log k) — глубина рекурсии log k, на каждом уровне все N узлов сливаются один раз
// Память: O(log k) — стек рекурсии

